请对以下 case 进行三维加权评分。

=== case_id ===
Case-22-express-006

=== 用户原始指令 (query.txt) ===
帮我整个多包裹列表，点开能看详情，红字标着快超时

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我整个多包裹列表，点开能看详情，红字标着快超时",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hwmusic://com.huawei.hmsapp.music/showMusicList?code=a001&type=4"
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "express": {
        "title": {
          "type": "string",
          "description": "快递物流卡片标题",
          "sampleValue": "包裹"
        },
        "packageCountLabel": {
          "type": "string",
          "description": "当前包裹数量摘要",
          "sampleValue": "2件"
        },
        "packages": [
          {
            "carrier": {
              "type": "string",
              "description": "第一件包裹的承运方或包裹简称",
              "sampleValue": "顺丰箱"
            },
            "timeLabel": {
              "type": "string",
              "description": "第一件包裹的剩余处理时间或时效提示",
              "sampleValue": "还剩2小时"
            },
            "statusLabel": {
              "type": "string",
              "description": "第一件包裹的状态标签，临近超时时显示警示文案",
              "sampleValue": "快超时"
            },
            "statusColor": {
              "type": "string",
              "description": "第一件包裹状态文字颜色，临近超时时为红色警示色",
              "sampleValue": "#ffe84026"
            }
          },
          {
            "carrier": {
              "type": "string",
              "description": "第二件包裹的承运方或包裹简称",
              "sampleValue": "京东件"
            },
            "timeLabel": {
              "type": "string",
              "description": "第二件包裹的当前物流时间提示",
              "sampleValue": "今日派送"
            },
            "statusLabel": {
              "type": "string",
              "description": "第二件包裹的状态标签",
              "sampleValue": "运输中"
            },
            "statusColor": {
              "type": "string",
              "description": "第二件包裹状态文字颜色",
              "sampleValue": "#99000000"
            }
          }
        ]
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/courier_box.png",
      "description": "彩色快递箱图标，适合用于物流信息、包裹列表和取件提醒场景。"
    }
  ]
}

